```
function sweptHit(ball, prev, brick) {
  // expand the brick by the ball radius; test the center segment
  const minX = brick.x - ball.r, maxX = brick.x + brick.w + ball.r;
  const minY = brick.y - ball.r, maxY = brick.y + brick.h + ball.r;
  const dx = ball.x - prev.x, dy = ball.y - prev.y;

  let tEnter = 0, tExit = 1;
  // X slab
  if (dx === 0) {
    if (prev.x < minX || prev.x > maxX) return null; // parallel, outside
  } else {
    let t0 = (minX - prev.x) / dx;
    let t1 = (maxX - prev.x) / dx;
    if (t0 > t1) [t0, t1] = [t1, t0];
    tEnter = Math.max(tEnter, t0);
    tExit = Math.min(tExit, t1);
    if (tEnter > tExit) return null;
  }
  // Y slab
  if (dy === 0) {
    if (prev.y < minY || prev.y > maxY) return null;
  } else {
    let t0 = (minY - prev.y) / dy;
    let t1 = (maxY - prev.y) / dy;
    if (t0 > t1) [t0, t1] = [t1, t0];
    tEnter = Math.max(tEnter, t0);
    tExit = Math.min(tExit, t1);
    if (tEnter > tExit) return null;
  }

  // tEnter is when the center enters the expanded box = first contact.
  // axis: whichever slab was entered last (larger t0).
  const t0x = dx === 0 ? 0 : Math.min((minX - prev.x) / dx, (maxX - prev.x) / dx);
  const t0y = dy === 0 ? 0 : Math.min((minY - prev.y) / dy, (maxY - prev.y) / dy);
  const axis = t0x > t0y ? 'x' : t0y > t0x ? 'y' : 'both';
  return { t: tEnter, axis };
}
```

