// Swept circle-vs-AABB: does the ball's center segment (prev -> ball) cross
// the brick expanded by the ball radius? Returns the entry time t in [0,1]
// and the face hit, or null when there is no crossing.
function sweptBrickHit(ball, prev, brick) {
  const minX = brick.x - ball.r;
  const maxX = brick.x + brick.w + ball.r;
  const minY = brick.y - ball.r;
  const maxY = brick.y + brick.h + ball.r;
  const dx = ball.x - prev.x;
  const dy = ball.y - prev.y;

  let t0x = -Infinity, t1x = Infinity;
  if (dx === 0) {
    if (prev.x < minX || prev.x > maxX) return null;
  } else {
    t0x = (minX - prev.x) / dx;
    t1x = (maxX - prev.x) / dx;
    if (t0x > t1x) { const t = t0x; t0x = t1x; t1x = t; }
  }

  let t0y = -Infinity, t1y = Infinity;
  if (dy === 0) {
    if (prev.y < minY || prev.y > maxY) return null;
  } else {
    t0y = (minY - prev.y) / dy;
    t1y = (maxY - prev.y) / dy;
    if (t0y > t1y) { const t = t0y; t0y = t1y; t1y = t; }
  }

  const tEnter = Math.max(t0x, t0y);
  const tExit = Math.min(t1x, t1y);
  if (tEnter > tExit || tEnter >= 1) return null;
  if (tEnter <= 0) return null; // already touching at the start: handled by the overlap pass

  const axis = t0x > t0y ? 'x' : t0y > t0x ? 'y' : 'both';
  return { t: tEnter, axis };
}
```

