export function resolveBricks(state) {
  const { ball, bricks } = state;
  const prev = { x: ball.px ?? ball.x, y: ball.py ?? ball.y };
  const destroyed = [];

  // Phase 1 — swept collisions (tunnelling protection): the ball may have
  // crossed a brick between prev and now without ever overlapping it.
  // Every crossed brick is destroyed; the bounce is resolved once, from the
  // earliest crossing.
  let earliest = null;
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = sweptBrickHit(ball, prev, brick);
    if (!hit) continue;
    if (!earliest || hit.t < earliest.hit.t) earliest = { brick, hit };
  }
  if (earliest) {
    // kill every brick crossed by the sweep
    for (const brick of bricks) {
      if (!brick.alive) continue;
      if (sweptBrickHit(ball, prev, brick)) {
        brick.alive = false;
        destroyed.push(brick);
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);
      }
    }
    // resolve the bounce at the earliest contact point
    const { brick, hit } = earliest;
    const cx = prev.x + (ball.x - prev.x) * hit.t;
    const cy = prev.y + (ball.y - prev.y) * hit.t;
    bounceAt(ball, brick, cx, cy, hit.axis);
  }

  // Phase 2 — current overlaps (normal + seams), resolved against the union
  // box of every overlapped brick so a seam bounce applies exactly once.
  let guard = 0;
  while (guard++ < 16) {
    const overlapped = bricks.filter((b) => b.alive && collides(ball, b));
    if (overlapped.length === 0) break;
    const box = unionBox(overlapped);
    bounceOut(ball, box);
    for (const brick of overlapped) {
      brick.alive = false;
      destroyed.push(brick);
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
  }

  return destroyed;
}
```

