function bounceAt(ball, brick, cx, cy, axis) {
  const centerX = brick.x + brick.w / 2;
  const centerY = brick.y + brick.h / 2;
  if (axis === 'x') {
    const fromLeft = cx < centerX;
    if (fromLeft ? ball.vx > 0 : ball.vx < 0) ball.vx = -ball.vx;
    ball.x = fromLeft ? brick.x - ball.r : brick.x + brick.w + ball.r;
    ball.y = cy;
  } else if (axis === 'y') {
    const fromTop = cy < centerY;
    if (fromTop ? ball.vy > 0 : ball.vy < 0) ball.vy = -ball.vy;
    ball.y = fromTop ? brick.y - ball.r : brick.y + brick.h + ball.r;
    ball.x = cx;
  } else {
    const fromLeft = cx < centerX;
    const fromTop = cy < centerY;
    if (fromLeft ? ball.vx > 0 : ball.vx < 0) ball.vx = -ball.vx;
    if (fromTop ? ball.vy > 0 : ball.vy < 0) ball.vy = -ball.vy;
    ball.x = fromLeft ? brick.x - ball.r : brick.x + brick.w + ball.r;
    ball.y = fromTop ? brick.y - ball.r : brick.y + brick.h + ball.r;
  }
}
