function unionBox(bricks) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const b of bricks) {
    minX = Math.min(minX, b.x);
    minY = Math.min(minY, b.y);
    maxX = Math.max(maxX, b.x + b.w);
    maxY = Math.max(maxY, b.y + b.h);
  }
  return { x: minX, y: minY, w: maxX - minX, h: maxY - minY };
}

// Resolves the ball against a box (a brick, or the union of a seam group):
// the axis with the smaller penetration is the face hit — flip that velocity
// component, push the ball out, and leave the other component untouched. Equal
// penetrations = a corner hit: flip both and push out diagonally.
function bounceOut(ball, box) {
  const fromLeft = ball.x + ball.r - box.x;
  const fromRight = box.x + box.w - (ball.x - ball.r);
  const fromTop = ball.y + ball.r - box.y;
  const fromBottom = box.y + box.h - (ball.y - ball.r);
  const penX = Math.min(fromLeft, fromRight);
  const penY = Math.min(fromTop, fromBottom);

  if (penX < penY) {
    if (fromLeft < fromRight ? ball.vx > 0 : ball.vx < 0) ball.vx = -ball.vx;
    ball.x = fromLeft < fromRight ? box.x - ball.r : box.x + box.w + ball.r;
  } else if (penY < penX) {
    if (fromTop < fromBottom ? ball.vy > 0 : ball.vy < 0) ball.vy = -ball.vy;
    ball.y = fromTop < fromBottom ? box.y - ball.r : box.y + box.h + ball.r;
  } else {
    if (fromLeft < fromRight ? ball.vx > 0 : ball.vx < 0) ball.vx = -ball.vx;
    if (fromTop < fromBottom ? ball.vy > 0 : ball.vy < 0) ball.vy = -ball.vy;
    ball.x = fromLeft < fromRight ? box.x - ball.r : box.x + box.w + ball.r;
    ball.y = fromTop < fromBottom ? box.y - ball.r : box.y + box.h + ball.r;
  }
