  if (dx === 0) {
    if (prev.x < minX || prev.x > maxX) return null;
  } else {
    t0x = (minX - prev.x) / dx; t1x = (maxX - prev.x) / dx;
    if (t0x > t1x) [t0x, t1x] = [t1x, t0x];
  }
  let t0y = -Infinity, t1y = Infinity;
  if (dy === 0) {
    if (prev.y < minY || prev.y > maxY) return null;
  } else {
    t0y = (minY - prev.y) / dy; t1y = (maxY - prev.y) / dy;
    if (t0y > t1y) [t0y, t1y] = [t1y, t0y];
  }
  let tEnter = Math.max(t0x, t0y);
  const tExit = Math.min(t1x, t1y);
  if (tEnter > tExit || tEnter > 1 || tEnter <= 0) return null;

  // --- exact corner refinement ---
