```js
// Resolves the ball against every brick: destroys the bricks it hits, scores
// them, and bounces the ball off the group. Called from frame() (the logic
// still lives in the render loop — debt #2), but pure: no DOM.
//
// Phase 1 (swept): bricks the ball crossed between its previous and current
// position without ever overlapping (tunnelling). All of them are destroyed;
// the bounce is applied exactly once, at the earliest contact.
//
// Phase 2 (overlaps): bricks the ball currently overlaps, resolved against
// their union box so a seam bounce applies exactly once. Iterated because a
// push-out can land the ball in a neighbour; the "moving into" guard keeps
// each axis from flipping twice.
//
// Returns the list of destroyed bricks.
export function resolveBricks(state) {
  const { ball, bricks } = state;
  const prev = { x: ball.px ?? ball.x, y: ball.py ?? ball.y };
  const destroyed = [];

  // Phase 1 — swept collisions.
  const swept = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = sweptBrickHit(ball, prev, brick);
    if (hit) swept.push({ brick, hit });
  }
  if (swept.length > 0) {
    swept.sort((a, b) => a.hit.t - b.hit.t);
    for (const { brick } of swept) {
      brick.alive = false;
      destroyed.push(brick);
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
    bounceAt(ball, prev, swept[0].brick, swept[0].hit);
  }

  // Phase 2 — current overlaps.
  let safety = 0;
  while (safety++ < 16) {
    const overlapped = bricks.filter((b) => b.alive && collides(ball, b));
    if (overlapped.length === 0) break;
    bounceOut(ball, unionBox(overlapped));
    for (const brick of overlapped) {
      brick.alive = false;
      destroyed.push(brick);
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
  }

  return destroyed;
}
