```js
// --- Brick collision resolution -------------------------------------------
//
// The ball bounces off bricks with a proper per-face resolution, and the
// resolution NEVER lets the ball plow through, re-flip forever (sticky
// bounce), nor apply the same bounce twice across a seam (see #1):
//
//   per face    the axis with the SMALLER penetration is the face hit: flip vy
//               on a top/bottom hit, vx on a side hit, leave the other
//               component exactly as it was;
//   corner      equal penetrations = diagonal hit: flip both components;
//   push out    the ball is repositioned outside the brick rectangle,
//               otherwise it still overlaps next frame and re-flips forever;
//   neighbours  the grid gap (8 px) is smaller than the ball (14 px), so every
//               seam overlaps TWO bricks in the same pass: the whole
//               overlapping group is resolved against its union box, so the
//               bounce applies exactly once (vy = -vy twice cancels out and
//               the ball would go through);
//   tunnelling  detection is discrete (position before/after the move): at
//               level 6 the ball moves 35.5 px per 50 ms step, more than the
//               34 px needed to cross a brick — the move is SWEPT between the
//               two positions.
//
// The sweep is a continuous circle-vs-rectangle test: the ball's centre moves
// along a segment against the brick expanded by the ball radius. The
// axis-aligned expansion over-reaches at the corners (it can claim a hit while
// the ball is still up to r*sqrt(2) away), so corner entries are refined
// against the exact corner distance.

// Swept circle-vs-AABB between the previous and current ball positions.
// Returns { t, axis } for the earliest contact with the brick during the move
// (`t` in [0, 1], `axis` in 'x' | 'y' | 'both'), or null when the path never
// touches it.
function sweptBrickHit(ball, prev, brick) {
  // The brick grown by the ball radius: the centre crosses this box exactly
  // when the ball touches the brick.
  const minX = brick.x - ball.r;
  const maxX = brick.x + brick.w + ball.r;
  const minY = brick.y - ball.r;
  const maxY = brick.y + brick.h + ball.r;
  const dx = ball.x - prev.x;
  const dy = ball.y - prev.y;

  // Time interval during which the centre overlaps the expanded X slab.
  let t0x = -Infinity;
  let t1x = Infinity;
  if (dx === 0) {
    if (prev.x < minX || prev.x > maxX) return null;
  } else {
    t0x = (minX - prev.x) / dx;
    t1x = (maxX - prev.x) / dx;
    if (t0x > t1x) [t0x, t1x] = [t1x, t0x];
  }

  // Same for the Y slab.
  let t0y = -Infinity;
  let t1y = Infinity;
  if (dy === 0) {
    if (prev.y < minY || prev.y > maxY) return null;
  } else {
    t0y = (minY - prev.y) / dy;
    t1y = (maxY - prev.y) / dy;
    if (t0y > t1y) [t0y, t1y] = [t1y, t0y];
  }

  const tEnter = Math.max(t0x, t0y);
  const tExit = Math.min(t1x, t1y);
  // Not crossed, crossed after the move ends, or already touching at the
  // start (the overlap pass below handles that case).
  if (tEnter > tExit || tEnter > 1 || tEnter <= 0) return null;

  // Entry point on the expanded box.
  const cx = prev.x + dx * tEnter;
  const cy = prev.y + dy * tEnter;

  // If the centre entered through a CORNER region of the expanded box, the
  // axis-aligned expansion over-reaches (it can claim a hit while the ball is
  // still up to r*sqrt(2) away from the brick corner). Refine against the
  // exact corner: solve |P(t) - corner| = r and keep the entry root.
  const cornerX =
    cx < brick.x ? brick.x : cx > brick.x + brick.w ? brick.x + brick.w : null;
  const cornerY =
    cy < brick.y ? brick.y : cy > brick.y + brick.h ? brick.y + brick.h : null;

  if (cornerX !== null && cornerY !== null) {
    const p0x = prev.x - cornerX;
    const p0y = prev.y - cornerY;
    const a = dx * dx + dy * dy;
    const b = 2 * (p0x * dx + p0y * dy);
    const c = p0x * p0x + p0y * p0y - ball.r * ball.r;
    const disc = b * b - 4 * a * c;
    if (disc < 0) return null; // path stays more than r away: false positive
    const t = (-b - Math.sqrt(disc)) / (2 * a);
    if (t < 0 || t > 1) return null;
    return { t, axis: 'both' };
  }

  // Face contact: whichever slab the centre entered last is the face hit.
  const axis = t0x > t0y ? 'x' : t0y > t0x ? 'y' : 'both';
  return { t: tEnter, axis };
}

// Applies the bounce for a swept contact: flips the face component(s) and
// repositions the ball just outside the brick at the contact point.
function bounceAt(ball, prev, brick, hit) {
  const dx = ball.x - prev.x;
  const dy = ball.y - prev.y;
  const cx = prev.x + dx * hit.t;
  const cy = prev.y + dy * hit.t;

  if (hit.axis === 'x') {
    const fromLeft = cx < brick.x + brick.w / 2;
    if (fromLeft ? ball.vx > 0 : ball.vx < 0) ball.vx = -ball.vx;
    ball.x = fromLeft ? brick.x - ball.r : brick.x + brick.w + ball.r;
    ball.y = cy;
  } else if (hit.axis === 'y') {
    const fromTop = cy < brick.y + brick.h / 2;
    if (fromTop ? ball.vy > 0 : ball.vy < 0) ball.vy = -ball.vy;
    ball.y = fromTop ? brick.y - ball.r : brick.y + brick.h + ball.r;
    ball.x = cx;
  } else {
    // Corner: the ball is exactly touching (distance r from the corner) at the
    // contact point — flip both components, leave it there.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = cx;
    ball.y = cy;
  }
  ball.x = Math.max(ball.r, Math.min(WIDTH - ball.r, ball.x));
}

// Bounding box of a set of bricks (used to resolve a seam group as one).
function unionBox(bricks) {
  let x = Infinity;
  let y = Infinity;
  let right = -Infinity;
  let bottom = -Infinity;
  for (const brick of bricks) {
    x = Math.min(x, brick.x);
    y = Math.min(y, brick.y);
    right = Math.max(right, brick.x + brick.w);
    bottom = Math.max(bottom, brick.y + brick.h);
  }
  return { x, y, w: right - x, h: bottom - y };
}

// Resolves the ball against a box (a brick, or the union of a seam group):
// the axis with the smaller penetration is the face hit — flip that velocity
// component and push the ball out, leaving the other component untouched.
// Equal penetrations = a corner hit: flip both, push out diagonally. The
// "moving into" guard makes the resolution idempotent: a ball already moving
// away from the face is never flipped again, which prevents the sticky
// bounce (re-flip forever) and double-flips across a seam.
function bounceOut(ball, box) {
  const fromLeft = ball.x + ball.r - box.x;
  const fromRight = box.x + box.w - (ball.x - ball.r);
  const fromTop = ball.y + ball.r - box.y;
  const fromBottom = box.y + box.h - (ball.y - ball.r);
  const penX = Math.min(fromLeft, fromRight);
  const penY = Math.min(fromTop, fromBottom);

  if (penX < penY) {
    if (fromLeft < fromRight ? ball.vx > 0 : ball.vx < 0) ball.vx = -ball.vx;
    ball.x = fromLeft < fromRight ? box.x - ball.r : box.x + box.w + ball.r;
  } else if (penY < penX) {
    if (fromTop < fromBottom ? ball.vy > 0 : ball.vy < 0) ball.vy = -ball.vy;
    ball.y = fromTop < fromBottom ? box.y - ball.r : box.y + box.h + ball.r;
  } else {
    if (fromLeft < fromRight ? ball.vx > 0 : ball.vx < 0) ball.vx = -ball.vx;
    if (fromTop < fromBottom ? ball.vy > 0 : ball.vy < 0) ball.vy = -ball.vy;
    ball.x = fromLeft < fromRight ? box.x - ball.r : box.x + box.w + ball.r;
    ball.y = fromTop < fromBottom ? box.y - ball.r : box.y + box.h + ball.r;
  }
  ball.x = Math.max(ball.r, Math.min(WIDTH - ball.r, ball.x));
}

// Resolves the ball against every brick: destroys the bricks it hits, scores
// them, and bounces the ball off the group. Called from frame() (the logic
// still lives in the render loop — debt #2), but pure: no DOM involved.
//
//   phase 1 (swept)   bricks the ball CROSSED between its previous and current
//                     position without ever overlapping (tunnelling). All of
//                     them are destroyed; the bounce is applied exactly once,
//                     at the earliest contact.
//   phase 2 (overlap) bricks the ball currently overlaps, resolved against
//                     their union box so a seam bounce applies exactly once.
//                     Iterated because a push-out can land the ball in a
//                     neighbour; the "moving into" guard keeps each axis from
//                     flipping twice.
//
// Returns the list of destroyed bricks.
export function resolveBricks(state) {
  const { ball, bricks } = state;
  const prev = { x: ball.px ?? ball.x, y: ball.py ?? ball.y };
  const destroyed = [];

  // Phase 1 — swept collisions (tunnelling).
  const swept = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = sweptBrickHit(ball, prev, brick);
    if (hit) swept.push({ brick, hit });
  }
  if (swept.length > 0) {
    swept.sort((a, b) => a.hit.t - b.hit.t);
    for (const { brick } of swept) {
      brick.alive = false;
      destroyed.push(brick);
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
    bounceAt(ball, prev, swept[0].brick, swept[0].hit);
  }

  // Phase 2 — current overlaps (incl. seams), against the union box.
  let safety = 0;
  while (safety++ < 32) {
    const overlapped = bricks.filter((b) => b.alive && collides(ball, b));
    if (overlapped.length === 0) break;
    bounceOut(ball, unionBox(overlapped));
    for (const brick of overlapped) {
      brick.alive = false;
      destroyed.push(brick);
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
  }

  return destroyed;
}
