import('./neon.js').then((m) => {
  // exports check
  const exp = ['UP','DOWN','LEFT','RIGHT','WIDTH','HEIGHT','PADDLE_W','PADDLE_H','PADDLE_Y','BALL_R','BRICK_ROWS','BRICK_COLS','BRICK_W','BRICK_H','BRICK_GAP','BRICK_TOP','makeBricks','ballSpeed','createState','collides','comboMultiplier','scoreForBrick','loadBest','saveBest','step','frame','boot','resolveBricks'];
  const missing = exp.filter(e => typeof m[e] === 'undefined');
  console.log('missing exports:', missing.length ? missing : 'none');

  // gameplay simulation: 2000 frames at level 1, then level 6 speeds
  for (const level of [1, 6]) {
    const state = m.createState(level);
    let frames = 0, lost = 0;
    while (frames < 4000 && state.bricks.some(b => b.alive)) {
      if (frames % 97 === 0) state.paddle.x = 100 + ((frames * 137) % 400); // paddle wander
      const isLost = m.step(state, 1/60);
      if (isLost) { lost++; state.ball = m.createState(state.level).ball; }
      const destroyed = m.resolveBricks(state);
      if (destroyed.some(b => !Number.isFinite(state.ball.x) || !Number.isFinite(state.ball.y))) {
        console.log('NON-FINITE ball at level', level, 'frame', frames); process.exit(1);
      }
      // stuck detection: same brick set + same ball pos for 60 frames
      frames++;
    }
    console.log('level', level, 'frames:', frames, 'lives lost:', lost, 'score:', state.score, 'combo:', state.combo);
  }
});"

