  const state = m.createState(1);
  const brick = state.bricks.find((b) => b.y === 48 && b.x === 84);
  // Path through the expanded-box corner square, 9.9 px from the brick corner
  // (distance > r): must NOT break the brick.
  state.ball = { x: 84, y: 34, r: 7, vx: 140, vy: -140, px: 70, py: 48 };
  const destroyed = m.resolveBricks(state);
  console.log('near-miss destroyed:', destroyed.length, '(expect 0), ball:', state.ball.x, state.ball.y, state.ball.vx, state.ball.vy);

  // Real corner clip at the same corner: distance exactly r -> must break it.
  state2 = m.createState(1);
  const brick2 = state2.bricks.find((b) => b.y === 48 && b.x === 84);
  state2.ball = { x: 84, y: 48, r: 7, vx: 140, vy: 140, px: 70, py: 34 };
  const destroyed2 = m.resolveBricks(state2);
  console.log('corner clip destroyed:', destroyed2.length, '(expect 1), ball:', state2.ball.x.toFixed(2), state2.ball.y.toFixed(2), state2.ball.vx, state2.ball.vy);
});"
